#!/usr/bin/env node
/**
 * Generates the CLI package-docs index from the canonical
 * `packages/<package>/docs` directories.
 *
 * - `--check` verifies that the committed generated file is current.
 *
 * The public Mintlify guide is hand-authored and intentionally does not copy
 * package documentation. Package reference ships inside each npm archive and
 * is canonical in `packages/<package>/docs`.
 *
 * Idempotent.
 */
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { DOCUMENTED_PACKAGES, GENERATED_MARKER } from './lib/docs.mjs'

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const CLI_DOCS = path.join(ROOT, 'packages', 'cli', 'docs')
const CLI_PACKAGES_PAGE = path.join(CLI_DOCS, 'packages.md')

const check = process.argv.includes('--check')
const problems = []

function relative(file) {
  return path.relative(ROOT, file) || path.basename(file)
}

async function readText(file) {
  return readFile(file, 'utf8')
}

function parseFrontmatter(source) {
  const match = source.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?/)
  if (!match) return null
  const title = /^title:\s*(.+)$/m.exec(match[1])?.[1]?.trim().replace(/^["']|["']$/g, '')
  const description = /^description:\s*(.+)$/m.exec(match[1])?.[1]?.trim().replace(/^["']|["']$/g, '')
  return { title, description, match }
}

async function validatePackage(entry) {
  const manifestPath = path.join(ROOT, entry.dir, 'package.json')
  let pkg
  try {
    pkg = JSON.parse(await readText(manifestPath))
  } catch (error) {
    problems.push(`${relative(manifestPath)}: ${error.message}`)
    return null
  }
  if (pkg.name !== entry.name) {
    problems.push(`${relative(manifestPath)}: expected name ${entry.name}, found ${pkg.name}`)
  }
  if (!Array.isArray(pkg.files) || !pkg.files.includes('docs')) {
    problems.push(`${relative(manifestPath)}: files must include "docs"`)
  }
  const docsDir = path.join(ROOT, entry.dir, 'docs')
  for (const file of entry.required) {
    // packages.md is generated below and is validated by the archive checks,
    // not as a hand-authored source file.
    if (entry.slug === 'cli' && file === 'packages.md') continue
    const source = await readText(path.join(docsDir, file)).catch(() => null)
    if (source === null) {
      problems.push(`${relative(path.join(docsDir, file))}: required documentation file is missing`)
      continue
    }
    const frontmatter = parseFrontmatter(source)
    if (!frontmatter?.title) {
      problems.push(`${relative(path.join(docsDir, file))}: missing frontmatter title`)
    }
    if (!frontmatter?.description) {
      problems.push(`${relative(path.join(docsDir, file))}: missing frontmatter description`)
    }
  }
  return pkg
}

async function buildCliIndex(packages) {
  const rows = []
  for (const entry of DOCUMENTED_PACKAGES) {
    const pkg = packages.get(entry.slug)
    if (!pkg) continue
    const docsDir = path.join(ROOT, entry.dir, 'docs')
    const index = parseFrontmatter(await readText(path.join(docsDir, 'index.md')))
    const localPath =
      entry.slug === 'cli'
        ? 'index.md'
        : ['diagnostics', 'mcp', 'dashboard'].includes(entry.slug)
          ? `${entry.name}/docs/index.md (resolve from CLI)`
          : `../../${entry.slug}/docs/index.md`
    rows.push({
      ...entry,
      version: pkg.version,
      title: index?.title ?? entry.name,
      localPath,
    })
  }
  const lines = [
    '---',
    'title: Installed package documentation',
    'description: Generated index of the documented StackNext packages and their local documentation paths.',
    '---',
    '',
    `<!-- ${GENERATED_MARKER}. Do not edit this file. -->`,
    '',
    '# Installed package documentation',
    '',
    'This index is generated from the packages that ship documentation. It does',
    'not mean every package is installed in a project. Check the path before',
    'reading: optional packages can be absent.',
    '',
    'Versions in this table are the versions of the package that produced this',
    'archive. Read the `version` field in the package.json next to the docs',
    'directory to confirm the installed version.',
    '',
    '| Package | Version | Visibility | Role | Documentation |',
    '| --- | --- | --- | --- | --- |',
    ...rows.map(
      (row) =>
        `| \`${row.name}\` | ${row.version} | ${row.visibility} | ${row.role} | \`${row.localPath}\` |`,
    ),
    '',
    '## How to use this index',
    '',
    'Starting from `node_modules/@stacknext/cli/docs/`, read `index.md`. For every',
    'other package with a relative path, use the table. For example:',
    '',
    '```text',
    'node_modules/@stacknext/cli/docs/index.md',
    '../../next/docs/index.md   # from node_modules/@stacknext/cli/docs/',
    '```',
    '',
    'Do not assume an internal package is at the app-root `node_modules` path.',
    'For diagnostics, MCP and dashboard, resolve the package from the installed',
    'CLI so the docs match its dependency version, including hoisted installs.',
    'Run this from the project directory:',
    '',
    '```js',
    "const { createRequire } = require('node:module')",
    "const { dirname, join } = require('node:path')",
    "const cliRequire = createRequire(require.resolve('@stacknext/cli/package.json'))",
    "for (const name of ['@stacknext/diagnostics', '@stacknext/mcp', '@stacknext/dashboard']) {",
    "  console.log(join(dirname(cliRequire.resolve(`${name}/package.json`)), 'docs', 'index.md'))",
    '}',
    '```',
    '',
    'If resolution fails, the dependency is unavailable. Do not instruct an',
    'agent to read a missing package directory.',
    '',
    '## Public, optional and internal packages',
    '',
    '- **Public integration packages** are intended for direct installation when',
    '  the project uses the corresponding feature.',
    '- **Internal packages** are installed as dependencies of the CLI or another',
    '  package. Their docs are for maintainers and advanced contributors.',
    '- Optional packages (`@stacknext/playwright`, `@stacknext/drizzle` and',
    '  `@stacknext/prisma`) are only present when explicitly installed.',
    '',
    '## Related',
    '',
    '- `index.md` — local documentation entry point.',
    '- `agent-setup.md` — managed AGENTS.md, MCP and skill setup.',
    '- `commands.md` — CLI reference.',
    '',
  ]
  return lines.join('\n')
}

async function writeIfChanged(file, content) {
  const current = await readText(file).catch(() => null)
  if (current === content) return false
  if (!check) {
    await mkdir(path.dirname(file), { recursive: true })
    await writeFile(file, content)
  }
  return true
}

async function main() {
  const packages = new Map()
  for (const entry of DOCUMENTED_PACKAGES) {
    const pkg = await validatePackage(entry)
    if (pkg) packages.set(entry.slug, pkg)
  }
  if (problems.length > 0) {
    console.error(`${problems.length} documentation source problem(s):`)
    for (const problem of problems) console.error(`  - ${problem}`)
    process.exit(1)
  }

  const changed = await writeIfChanged(CLI_PACKAGES_PAGE, await buildCliIndex(packages))

  if (check && changed) {
    console.error(
      'Documentation output is out of date. Run `pnpm docs:sync`.\n  - packages/cli/docs/packages.md',
    )
    process.exit(1)
  }

  if (!check) {
    console.log(
      changed ? 'Updated packages/cli/docs/packages.md.' : 'Documentation is already up to date.',
    )
  }
}

await main()
